import { ICustomExercise, IExerciseKind, IEquipment, IMuscle, IProgram } from "../types";
import { Program_create } from "./program";

function buildCustomExercise(args: {
  id: string;
  name: string;
  types: IExerciseKind[];
  targetMuscles: IMuscle[];
  synergistMuscles?: IMuscle[];
  defaultEquipment?: IEquipment;
  smallImageUrl?: string;
  largeImageUrl?: string;
  videoUrl?: string;
}): ICustomExercise {
  return {
    vtype: "custom_exercise",
    id: args.id,
    name: args.name,
    isDeleted: false,
    defaultEquipment: args.defaultEquipment,
    types: args.types,
    smallImageUrl: args.smallImageUrl,
    largeImageUrl: args.largeImageUrl,
    videoUrl: args.videoUrl,
    meta: {
      targetMuscles: args.targetMuscles,
      synergistMuscles: args.synergistMuscles || [],
      bodyParts: [],
      sortedEquipment: args.defaultEquipment ? [args.defaultEquipment] : [],
    },
  };
}

function joinLines(lines: string[]): string {
  return lines.join("\n");
}

function builtInExerciseImageUrl(
  key: string,
  size: "small" | "large"
): string {
  return size === "large"
    ? `/externalimages/exercises/full/large/${key}_full_large.png`
    : `/externalimages/exercises/single/small/${key}_single_small.png`;
}

export function ClassicSplitPreset_build(): {
  program: IProgram;
  customExercises: Record<string, ICustomExercise>;
} {
  const customExercises: Record<string, ICustomExercise> = {
    classicSplitHighToLowCableFly: buildCustomExercise({
      id: "classicSplitHighToLowCableFly",
      name: "High-to-Low Cable Fly",
      defaultEquipment: "cable",
      types: ["upper", "push"],
      targetMuscles: ["Pectoralis Major Sternal Head"],
      synergistMuscles: ["Deltoid Anterior", "Pectoralis Major Clavicular Head"],
      smallImageUrl: builtInExerciseImageUrl("cablecrossover_cable", "small"),
      largeImageUrl: builtInExerciseImageUrl("cablecrossover_cable", "large"),
    }),
    classicSplitStraightArmCablePulldown: buildCustomExercise({
      id: "classicSplitStraightArmCablePulldown",
      name: "Straight-Arm Cable Pulldown",
      defaultEquipment: "cable",
      types: ["upper", "pull"],
      targetMuscles: ["Latissimus Dorsi"],
      synergistMuscles: ["Teres Major", "Trapezius Lower Fibers"],
      smallImageUrl: builtInExerciseImageUrl("latpulldown_cable", "small"),
      largeImageUrl: builtInExerciseImageUrl("latpulldown_cable", "large"),
    }),
    classicSplitPallofPress: buildCustomExercise({
      id: "classicSplitPallofPress",
      name: "Pallof Press",
      defaultEquipment: "cable",
      types: ["core"],
      targetMuscles: ["Obliques"],
      synergistMuscles: ["Rectus Abdominis"],
      smallImageUrl: builtInExerciseImageUrl("cabletwist_cable", "small"),
      largeImageUrl: builtInExerciseImageUrl("cabletwist_cable", "large"),
    }),
    classicSplitCableCurl: buildCustomExercise({
      id: "classicSplitCableCurl",
      name: "Cable Curl",
      defaultEquipment: "cable",
      types: ["upper", "pull"],
      targetMuscles: ["Biceps Brachii"],
      synergistMuscles: ["Brachialis", "Brachioradialis"],
      smallImageUrl: builtInExerciseImageUrl("bicepcurl_cable", "small"),
      largeImageUrl: builtInExerciseImageUrl("bicepcurl_cable", "large"),
    }),
  };

  const monday = joinLines([
    "// First lift: add 2 warm-up/ramp sets before work sets.",
    "Incline Bench Press, Smith Machine / 3x6-8",
    "Chest Press, Leverage Machine / 3x8-10",
    "Pec Deck / 2x12-15",
    "// Set the cables high and drive the handles down toward the lower chest.",
    "High-to-Low Cable Fly / 2x12-15",
    "// Clean sets only. Stop 1 rep before failure.",
    "Push Up / 2x8-20",
    "mon-crunch: Cable Crunch / 3x10-15",
    "// Use the captain's chair if your gym has one.",
    "Knee Raise / 2x10-15",
  ]);

  const tuesday = joinLines([
    "// First lift: add 2 warm-up/ramp sets before work sets.",
    "Lat Pulldown / 3x6-10",
    "// Use the chest-supported row machine when available.",
    "Chest-Supported Row, Leverage Machine / 3x8-10",
    "// Use a neutral grip if your cable row attachment allows it.",
    "Seated Row, Cable / 3x10-12",
    "Straight-Arm Cable Pulldown / 2x12-15",
    "Reverse Fly, Leverage Machine / 3x12-15",
  ]);

  const wednesday = joinLines([
    "// First lift: add 2 warm-up/ramp sets before work sets.",
    "Squat, Smith Machine / 3x6-8",
    "Leg Press, Leverage Machine / 3x10-12",
    "// Dumbbells are the default. Swap to the Smith version if needed.",
    "Romanian Deadlift / 3x8-10",
    "Leg Curl, Leverage Machine / 3x10-12",
    "// Count each work set as 10 walking steps per leg.",
    "Lunge, Dumbbell / 2x10",
    "leg-calf: Standing Calf Raise, Smith Machine / 4x10-15",
  ]);

  const thursday = joinLines([
    "// First lift: add 2 warm-up/ramp sets before work sets.",
    "Shoulder Press / 3x6-8",
    "machine-lateral: Lateral Raise, Leverage Machine / 3x12-15",
    "// Run one arm at a time when needed.",
    "cable-lateral: Lateral Raise, Cable / 2x12-15",
    "Reverse Fly, Leverage Machine / 3x12-15",
    "Face Pull / 2x12-15",
    "Shrug / 2x10-12",
    "// Brace hard and control the press-out on both sides.",
    "Pallof Press / 2x10-12",
    "thu-crunch: Cable Crunch / 2x12-15",
  ]);

  const friday = joinLines([
    "// First lift: add 2 warm-up/ramp sets before work sets.",
    "Bench Press Close Grip, Smith Machine / 3x8-10",
    "Triceps Pushdown / 3x10-12",
    "// Keep the elbows high and let the rope travel behind the head.",
    "Triceps Extension, Cable / 2x12-15",
    "Cable Curl / 3x8-10",
    "Incline Curl / 3x10-12",
    "Hammer Curl / 2x12-15",
    "arm-calf: Calf Press on Leg Press / 3x12-15",
  ]);

  const saturday = joinLines([
    "// Keep this day lighter than the main body-part days.",
    "Incline Chest Press, Leverage Machine / 2x10-12",
    "High Row, Leverage Machine / 2x10-12",
    "Leg Extension / 2x12-15",
    "Seated Leg Curl / 2x12-15",
    "sat-lateral: Lateral Raise, Cable / 2x15-20",
    "sat-crunch: Cable Crunch / 3x12-15",
    "// Hold each side for 30-45 seconds with clean breathing.",
    "Side Plank / 2x1 30s",
  ]);

  const sunday = "";

  const program = {
    ...Program_create("Modified Classic Split"),
    shortDescription: "5 hard body-part days, 1 lighter touch day, 1 full rest day.",
    description: joinLines([
      "### Session rules",
      "- First lift of the day: 2 warm-up/ramp sets before the work sets.",
      "- Compounds: rest 2-3 minutes.",
      "- Isolations: rest 60-90 seconds.",
      "- Finish most sets with 1-2 reps in reserve.",
      "- Only the last set of smaller isolation moves should get very close to failure.",
      "",
      "### 12-week roadmap",
      "- Weeks 1-4: build the base. Add reps first and keep cardio exactly as written.",
      "- Weeks 5-7: push the main lifts harder. If recovery is good, add 1 extra set only to Smith incline bench, lat pulldown, and leg press.",
      "- Week 8: deload. Cut lifting sets roughly in half, keep 3 RIR, and skip Friday intervals.",
      "- Weeks 9-11: hardest push. Try to beat week-7 numbers without adding junk volume.",
      "- Week 12: consolidate. Keep loads fairly heavy and cut lifting volume by about 25-30%.",
      "",
      "### Cardio anchor",
      "- Tuesday: 20 min zone-2.",
      "- Thursday: 20 min zone-2.",
      "- Friday: 6 rounds of 45 sec hard / 75 sec easy.",
      "- Saturday: 30-35 min zone-2 incline walk.",
      "- Add a 10-minute walk after dinner most days, especially after carb-heavy meals.",
      "",
      "### Nutrition and tracking",
      "- Protein target: 160-190 g/day.",
      "- Pre-workout: 25-35 g protein plus 30-60 g carbs 60-120 min before lifting.",
      "- Post-workout: 30-40 g protein plus a normal carb serving within 1-3 hours.",
      "- At dinner, eat protein and vegetables first, then rice or roti.",
      "- Track a 4-day morning bodyweight average, weekly waist at navel, and front/side photos every 2 weeks.",
    ]),
    author: "Local preset",
    tags: ["hypertrophy"],
    planner: {
      vtype: "planner" as const,
      name: "Modified Classic Split",
      weeks: [
        {
          name: "Week 1",
          description: "Repeat this weekly split while following the 12-week roadmap in the plan notes above.",
          days: [
            {
              name: "Monday",
              description: joinLines([
                "Chest + abs.",
                "",
                "- Cardio: 10 minutes easy incline walk after lifting.",
                "- Effort: stay around 1-2 RIR on most work sets.",
              ]),
              exerciseText: monday,
            },
            {
              name: "Tuesday",
              description: joinLines([
                "Back + rear delts.",
                "",
                "- Cardio: 20 minutes zone-2 treadmill, bike, or elliptical.",
                "- Pace: steady enough that you can still talk in short sentences.",
              ]),
              exerciseText: tuesday,
            },
            {
              name: "Wednesday",
              description: joinLines([
                "Legs + calves.",
                "",
                "- Cardio: optional 8-10 minute easy bike cooldown only.",
                "- Keep the main leg work crisp and do not turn the cooldown into conditioning.",
              ]),
              exerciseText: wednesday,
            },
            {
              name: "Thursday",
              description: joinLines([
                "Shoulders + abs.",
                "",
                "- Cardio: 20 minutes zone-2.",
                "- Rear-delts and cable raises stay controlled; save failure for the last small isolation set only.",
              ]),
              exerciseText: thursday,
            },
            {
              name: "Friday",
              description: joinLines([
                "Arms + calves.",
                "",
                "- Cardio: 10-12 minutes of intervals on a bike or elliptical.",
                "- Interval structure: 45 sec hard, 75 sec easy, repeat 6 rounds.",
              ]),
              exerciseText: friday,
            },
            {
              name: "Saturday",
              description: joinLines([
                "Upper/leg touch-up + conditioning.",
                "",
                "- Keep this day lighter than the main days.",
                "- Cardio: 30-35 minutes zone-2 incline walk.",
              ]),
              exerciseText: saturday,
            },
            {
              name: "Sunday",
              description: joinLines([
                "Full rest day.",
                "",
                "- No hard lifting.",
                "- Aim for 45-60 minutes of easy walking across the day.",
              ]),
              exerciseText: sunday,
            },
          ],
        },
      ],
    },
  } satisfies IProgram;

  return { program, customExercises };
}
